import sys
sys.setrecursionlimit(1000000)
from collections import deque
from collections import defaultdict

n = int(input())
s = str(input())
s = list(s)

sakuzyo = deque([])
ans = []

for i,mozi in enumerate(s):
    if mozi == "(":
        sakuzyo.append(i)
    elif mozi == ")":
        if sakuzyo:
            start = sakuzyo.pop()
            if not any(char in s[start:i] for char in "()"):
                del ans[start:i+1]
        else:
            ans.append(mozi)
    else:
        ans.append(mozi)

print("".join(ans))
